import type { AirCityRecord } from '../data/ecology'
import type { MotionProfile } from '../hooks/useMotionProfile'

const clamp = (value: number, minimum: number, maximum: number) => Math.min(maximum, Math.max(minimum, value))

export const particleCountForProfile = (profile: MotionProfile) => profile === 'full' ? 48000 : profile === 'lite' ? 20400 : 10800

export const sampleTerrainHeight = (x: number, z: number) => {
  const peak = (cx: number, cz: number, spread: number, height: number) => Math.exp(-((x - cx) ** 2 + (z - cz) ** 2) / spread) * height
  const massif = peak(-2.25, .55, 4.2, 2.25) + peak(.15, -.35, 3.1, 1.8) + peak(2.45, .8, 2.6, 1.7) + peak(1.2, -2.3, 2.15, 1.15)
  const ridges = Math.sin(x * 1.34 + z * .44) * .29 + Math.cos(z * 1.58 - x * .3) * .22
  const detail = Math.sin((x + z) * 3.4) * .075 + Math.cos((x - z) * 4.1) * .055
  const basin = peak(.85, .5, .82, .72)
  const edge = Math.max(0, Math.hypot(x / 6.3, z / 4.8) - .72) * .65
  return clamp(massif + ridges + detail - basin - edge - .76, -1.18, 2.72)
}

export const mapRecordToTerrain = (record: Pick<AirCityRecord, 'x' | 'y'>) => {
  const x = (record.x - 50) / 50 * 5.05
  const z = (record.y - 50) / 50 * 3.55
  return { x, z, y: sampleTerrainHeight(x, z) + .16 }
}
